from typing import List

class Solution:
    def decrypt(self, code: List[int], k: int) -> List[int]:
        length = len(code)
        code += code
        for i in range(length):
            formula = {True : sum(code[i+1:i+1+k]), False : sum(code[i+length+k:i+length])}
            code[i] = formula[k>=0]
        return code[:length]

# Input: code = [5,7,1,4], k = 3
